from pathlib import Path
import json
p=Path(__file__).resolve().parent/'composition'
css="""@font-face{font-family:'Roca One';src:url('fonts/RocaOne-Rg.ttf')}@font-face{font-family:Montserrat;src:url('fonts/Montserrat-Regular.ttf');font-weight:100 900}*{box-sizing:border-box;margin:0;padding:0}html,body{width:1080px;height:1920px;overflow:hidden;background:#f7f6f2;color:#1c211e;font-family:Montserrat}#root{position:absolute;inset:0}h1,h2,.display{font-family:'Roca One';font-weight:400;line-height:1.08;letter-spacing:-2px}h1,h2{font-size:98px}p{font-size:34px;line-height:1.45}.eyebrow{font-size:30px;letter-spacing:5px;text-transform:uppercase}.ground{position:absolute;inset:0;background:#f7f6f2}.mint{background:#afd5b6}.brand{font-family:'Roca One';font-size:92px;letter-spacing:-3px}.stripe{position:absolute;left:0;right:0;top:0;height:120px;background:repeating-linear-gradient(90deg,#afd5b6 0 62px,#f7f6f2 62px 115px)}.cup-crop{position:absolute;width:682px;height:910px;overflow:hidden}.cup-crop img{position:absolute;width:1365px;height:910px;max-width:none;top:0;left:0}.cup-crop.matcha img{left:-682px}.qr{background:white;border-radius:22px;padding:8px;object-fit:contain}.phone{border:14px solid #1c211e;border-radius:62px;overflow:hidden;box-shadow:0 28px 50px #1c211e25;background:#fff}.phone img{width:100%;height:100%;object-fit:cover;object-position:top}.rule{height:2px;background:#1c211e35}"""
(p/'assets/style.css').write_text(css)
def cups(prefix,small=False):
 return f'''<div id="{prefix}-cups" data-layout-allow-overflow><div id="{prefix}-coffee" class="cup-crop"><img id="{prefix}-coffee-image" src="assets/images/flying-drinks.png" alt="Café Blanco en suspension avec éclaboussure"></div><div id="{prefix}-matcha" class="cup-crop matcha"><img id="{prefix}-matcha-image" src="assets/images/flying-drinks.png" alt="Matcha glacé Blanco en suspension avec éclaboussure"></div></div>'''
def scene(name,style,body,anim):
 (p/'compositions'/f'{name}.html').write_text(f'''<template><style>#root{{position:absolute;inset:0}}{style}</style><div id="root" data-composition-id="{name}" data-width="1080" data-height="1920">{body}</div><script>const tl=gsap.timeline({{paused:true}});{anim}window.__timelines.{name}=tl;</script></template>''')
def intro(selector,time=.05):
 return f"tl.fromTo('{selector}',{{y:40,opacity:0}},{{y:0,opacity:1,duration:.75,ease:'power4.out'}},{time});"
def fly(prefix):
 return f"""tl.fromTo('#{prefix}-coffee',{{x:-540,y:300,rotation:-24,scale:.75}},{{x:0,y:0,rotation:-7,scale:1,duration:1.25,ease:'power4.out'}},.2);tl.fromTo('#{prefix}-matcha',{{x:600,y:360,rotation:30,scale:.8}},{{x:0,y:0,rotation:8,scale:1,duration:1.35,ease:'power4.out'}},.35);tl.to('#{prefix}-coffee',{{y:-28,rotation:-1,duration:2.8,ease:'sine.inOut'}},1.5);tl.to('#{prefix}-matcha',{{y:-40,rotation:2,duration:2.8,ease:'sine.inOut'}},1.7);"""
scene('hook',"""#hook-brand{position:absolute;left:90px;top:180px}#hook-place{position:absolute;right:90px;top:230px;font-size:30px}#hook-title{position:absolute;left:90px;top:350px;width:900px}#hook-cups{position:absolute;inset:0}#hook-coffee{left:-45px;top:705px}#hook-matcha{left:470px;top:760px}#hook-label{position:absolute;left:90px;bottom:195px;font-size:32px;letter-spacing:7px}#hook-note{position:absolute;left:90px;bottom:130px;font-size:30px}""",'''<div class="ground"></div><div class="stripe"></div><div id="hook-brand" class="brand">Blanco</div><div id="hook-place">GRENOBLE</div><h1 id="hook-title">Votre pause,<br>version Blanco.</h1>'''+cups('hook')+'''<div id="hook-label">CAFÉ · MATCHA</div><p id="hook-note">Coffee &amp; More, à votre façon.</p>''',intro('#hook-title')+fly('hook')+intro('#hook-label, #hook-note',1.1)+"tl.to('#hook-coffee',{x:-650,y:-80,rotation:-22,duration:.5,ease:'power3.in'},4.9);tl.to('#hook-matcha',{x:650,y:80,rotation:22,duration:.5,ease:'power3.in'},4.95);")
scene('tastes',"""#tastes-kicker{position:absolute;left:90px;top:185px}#tastes-title{position:absolute;left:90px;top:275px;width:900px}#tastes-visual{position:absolute;left:90px;top:650px;width:680px;height:600px;border-radius:40px;overflow:hidden}#tastes-photo{width:100%;height:100%;object-fit:cover}#tastes-phone{position:absolute;left:705px;top:640px;width:280px;height:580px;border-width:9px;border-radius:34px}#tastes-names{position:absolute;left:90px;top:1330px;width:900px}#tastes-names .display{font-size:52px;margin-bottom:28px}#tastes-names p{font-size:33px;margin-top:20px}#tastes-origin{position:absolute;left:90px;bottom:180px;font-size:30px;letter-spacing:2px}""",'''<div class="ground mint"></div><p id="tastes-kicker" class="eyebrow">BLANCO SIGNATURES</p><h2 id="tastes-title">Des saveurs<br>à partager.</h2><div id="tastes-visual"><img id="tastes-photo" src="assets/images/sandwich.jpg" alt="Illustration des petites faims du menu Blanco"></div><div id="tastes-phone" class="phone" data-layout-allow-overlap><img id="tastes-menu-screen" src="assets/images/menu-screen.png" alt="Vraie carte Blanco en ligne"></div><div id="tastes-names"><div id="tastes-coffee" class="display">Syrian coffee · Syrian tea</div><div class="rule"></div><p id="tastes-food">Halloumi · Labneh · Hoummous</p></div><div id="tastes-origin">SYRIE · TURQUIE · LIBAN</div>''',intro('#tastes-title')+"tl.fromTo('#tastes-visual',{x:-300,rotation:-8,opacity:0},{x:0,rotation:0,opacity:1,duration:.9,ease:'power4.out'},.1);tl.fromTo('#tastes-phone',{x:260,y:80,rotation:12,opacity:0},{x:0,y:0,rotation:4,opacity:1,duration:1,ease:'power4.out'},.3);"+intro('#tastes-coffee',.7)+intro('#tastes-food',1.35)+intro('#tastes-origin',1.6)+"tl.to('#tastes-visual',{y:-18,duration:3.4,ease:'sine.inOut'},1.1);tl.to('#tastes-phone',{y:-25,rotation:2,duration:3.4,ease:'sine.inOut'},1.3);")
scene('club',"""#club-kicker{position:absolute;left:90px;top:180px}#club-title{position:absolute;left:90px;top:275px;width:900px;font-size:89px}#club-phone{position:absolute;left:100px;top:660px;width:480px;height:980px}#club-panel{position:absolute;left:640px;top:775px;width:330px}#club-qr{width:330px;height:330px}#club-instruction{font-size:39px;margin-top:35px;line-height:1.3}#club-bottom{position:absolute;left:90px;bottom:160px;width:900px;font-size:34px}#club-ring{position:absolute;left:620px;top:755px;width:370px;height:370px;border:4px solid #467554;border-radius:40px}""",'''<div class="ground"></div><div class="stripe"></div><div id="club-kicker" class="eyebrow">LE CLUB BLANCO</div><h2 id="club-title">Votre fidélité<br>récompensée.</h2><div id="club-phone" class="phone"><img id="club-screen" src="assets/images/loyalty-signup.png" alt="Vraie page d’inscription à la fidélité Blanco"></div><div id="club-ring" data-layout-ignore></div><div id="club-panel"><img id="club-qr" class="qr" src="assets/images/loyalty-qr.png" alt="QR pour créer votre carte Blanco"><p id="club-instruction">Scannez.<br>Créez<br>votre carte.</p></div><p id="club-bottom">Cumulez des tampons.<br>Profitez de cadeaux.</p>''',intro('#club-title',0)+"tl.fromTo('#club-phone',{y:180,rotation:-8,opacity:0},{y:0,rotation:-2,opacity:1,duration:1,ease:'power4.out'},.15);"+intro('#club-panel',.5)+intro('#club-bottom',1.3)+"tl.fromTo('#club-ring',{scale:.85,opacity:0},{scale:1,opacity:1,duration:.55,ease:'power3.out'},1.5);tl.to('#club-ring',{scale:1.1,opacity:0,duration:.6,ease:'power2.out'},2.05);tl.to('#club-phone',{y:-18,rotation:0,duration:3.5,ease:'sine.inOut'},1.4);")
scene('outro',"""#outro-logo{position:absolute;left:90px;top:215px;font-size:150px}#outro-sub{position:absolute;left:95px;top:400px;font-size:32px;letter-spacing:6px}#outro-title{position:absolute;left:90px;top:560px;font-size:76px;width:900px}#outro-cups{position:absolute;inset:0}#outro-coffee{left:-160px;top:880px}#outro-matcha{left:430px;top:930px}#outro-cups .cup-crop{width:546px;height:728px}#outro-cups img{width:1092px;height:728px}#outro-cups .matcha img{left:-546px}#outro-cta{position:absolute;left:90px;bottom:170px;display:flex;gap:36px;align-items:center}#outro-qr{width:200px;height:200px}#outro-cta p{font-size:35px}#outro-credit{position:absolute;left:90px;bottom:90px;font-size:28px}""",'''<div class="ground mint"></div><div id="outro-logo" class="brand">Blanco</div><div id="outro-sub">COFFEE &amp; MORE · GRENOBLE</div><h2 id="outro-title">On se retrouve<br>chez Blanco.</h2>'''+cups('outro')+'''<div id="outro-cta"><img id="outro-qr" class="qr" src="assets/images/menu-qr.png" alt="QR de la carte Blanco"><p>Découvrez la carte.<br>Et trouvez votre préféré.</p></div><p id="outro-credit">Musique : Sascha Ende · ende.app · CC BY 4.0</p>''',intro('#outro-logo',0)+intro('#outro-title',.2)+fly('outro')+intro('#outro-cta',.7))
variables=[dict(id='color-ground',type='color',label='Papier',default='#f7f6f2'),dict(id='color-accent',type='color',label='Menthe Blanco',default='#afd5b6'),dict(id='color-ink',type='color',label='Encre',default='#1c211e')]
hosts=''.join(f'<div id="{n}" class="clip" data-composition-id="{n}" data-composition-src="compositions/{n}.html" data-start="{i*5.5}" data-duration="5.5" data-track-index="1" data-track-kind="graphics" data-width="1080" data-height="1920"></div>' for i,n in enumerate(['hook','tastes','club','outro']))
audio='''<audio id="bg-music" class="clip" data-start="0" data-duration="22" data-track-index="10" data-volume="0.30" data-fade-in="0.4" data-fade-out="1.8" src="assets/music/music.mp3"></audio>'''
for name,t,src,vol,dur in [('open',.4,'reveal',.45,.18),('tastes',5.65,'reveal',.4,.18),('scan',12.5,'click',.5,.05),('outro',17.47,'reveal',.4,.18)]:
 audio+=f'<audio id="sfx-{name}" class="clip" data-start="{t}" data-duration="{dur}" data-track-index="11" data-volume="{vol}" src="assets/sfx/{src}.ogg"></audio>'
(p/'index.html').write_text('''<!doctype html><html lang="fr" data-resolution="portrait" data-composition-variables='''+"'"+json.dumps(variables)+"'"+'''><head><meta charset="utf-8"><meta name="viewport" content="width=1080,height=1920"><title>Blanco — Votre pause à Grenoble</title><script src="assets/vendor/gsap.min.js"></script><link rel="stylesheet" href="assets/style.css"></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="22" data-width="1080" data-height="1920" data-fps="30">'''+hosts+audio+'''</div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true});</script></body></html>''')
